def link_earlier_payouts(apps, schema_editor):
    """Payouts sent before this change covered every visit up to their time."""
    Payout = apps.get_model('payments', 'Payout')
    Payment = apps.get_model('payments', 'Payment')
    Refund = apps.get_model('payments', 'Refund')
    sent = Payout.objects.filter(kind='earnings').exclude(status__in=('FAILED', 'DENIED', 'CANCELED'))
    for payout in sent.order_by('created_at', 'pk'):
        Payment.objects.filter(restroom_id=payout.restroom_id, payout__isnull=True,
                               created_at__lte=payout.created_at).update(payout=payout)
        Refund.objects.filter(payment__restroom_id=payout.restroom_id, payout__isnull=True,
                              created_at__lte=payout.created_at).update(payout=payout)


